#include <stdio.h>

/* teste do desafio de MODULO a-ficha-do-caixa — counter_protocol (03-tdd 3.9.3).
   Cada cenario escreve num arquivo o que a pessoa digitaria, aponta o stdin
   para esse arquivo (freopen) e captura o stdout no proprio teste. Os nomes
   dos temporarios sao POR CENARIO: um cenario nunca le a entrada nem a
   captura do outro. Nunca ha fclose de stdin/stdout — so fflush. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void aFichaDoCaixa(void);

SM_TEST(duas_unidades_de_350) {
    /* venda comum: dois paes de 3,50 */
    FILE *e = fopen("sm_entrada_1.tmp", "w");
    fprintf(e, "2 350\n");
    fclose(e);
    freopen("sm_entrada_1.tmp", "r", stdin);

    freopen("sm_saida_1.tmp", "w", stdout);
    aFichaDoCaixa();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[120] = "(nada impresso)";
    fgets(linha, 120, f);
    checa_str("as unidades digitadas", linha, "unidades: 2\n",
              "a primeira linha devolve o primeiro numero digitado");
    fgets(linha, 120, f);
    checa_str("o preco unitario", linha, "preco unitario: 350 centavos\n",
              "a segunda linha devolve o segundo numero digitado");
    fgets(linha, 120, f);
    checa_str("o total em reais e centavos", linha, "total: 7 reais e 0 centavos\n",
              "o total sai da multiplicacao, e a quebra sai da divisao inteira e do resto");
    fgets(linha, 120, f);
    checa_str("a media por unidade", linha, "media por unidade: 3.500000\n",
              "a media tem casas decimais: o cast faz a divisao virar real");
    fgets(linha, 120, f);
    checa_str("o sinalizador de caro", linha, "caro: 0\n",
              "a comparacao com 1000 ja vale 0 ou 1");
    fgets(linha, 120, f);
    checa_str("o frete e o brinde", linha, "com frete e brinde: 750 centavos e 3 unidades\n",
              "o += somou o frete no total e o ++ somou o brinde nas unidades");
    fgets(linha, 120, f);
    checa_str("a devolucao", linha, "com a devolucao: 400 centavos, unidades: 2\n",
              "o -= devolveu o preco de uma unidade e o -- tirou a unidade devolvida");
    char fim[120] = "(nada impresso)";
    fgets(fim, 120, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a ficha termina na setima linha");
    fclose(f);
}

