#include <stdio.h>

void aFichaDoCaixa(void) {
    int unidades = 0;
    int precoCentavos = 0;
    scanf("%d %d", &unidades, &precoCentavos);

    int total = unidades * precoCentavos;
    int reais = total / 100;
    int centavos = total % 100;
    double media = (double)reais / unidades;
    int caro = precoCentavos >= 1000;

    printf("unidades: %d\n", unidades);
    printf("preco unitario: %d centavos\n", precoCentavos);
    printf("total: %d reais e %d centavos\n", reais, centavos);
    printf("media por unidade: %f\n", media);
    printf("caro: %d\n", caro);

    total += 50;
    unidades++;
    printf("com frete e brinde: %d centavos e %d unidades\n", total, unidades);
    total -= precoCentavos;
    unidades--;
    printf("com a devolucao: %d centavos, unidades: %d\n", total, unidades);
}
